export interface DossierCheckResult {
  observations: DossierObservation[];
  provider: string;
}

/* ── AI Provider & BYOK Configuration ───────────────────────────── */

export type AiProviderType =
  | "openai"
  | "anthropic"
  | "google"
  | "anthropic-compatible"
  | "openai-compatible"
  | "deepseek"
  | "openrouter"
  | "ollama"
  | "zai"
  | "minimax"
  // Voice only: Fish Audio speaks and transcribes but is not an LLM, so it
  // never counts as a provider for persona/rubric work.
  | "fishaudio"
  // Voice only, spoken in the browser: Supertonic runs fully on-device via
  // WebGPU/WASM (transformers.js) with the model downloaded once. No key, no
  // server, no account — the free/offline voice. Auto-registered by the
  // browser bridge, never configured by hand.
  | "supertonic"
  // Desktop-only: native LiteRT (Gemma 4 E4B) served on loopback by the
  // Electrobun shell. Auto-registered, never added by hand — see desktop-bridge.
  | "litert";

export interface AiProviderConfig {
  id: string;
  name: string;
  type: AiProviderType;
  /** Provider identifier from models.dev, when configured from its catalog. */
  modelsDevId?: string;
  apiKey: string;
  baseUrl?: string;
  defaultModel: string;
  availableModels?: string[];
  /** Modality metadata for models discovered from models.dev. */
  modelModalities?: Record<string, AiModelModalities>;
  /** OpenAI-compatible text-generation wire protocol. Defaults to chat. */
  apiMode?: "chat" | "responses";
  /**
   * How hard to think, per model id.
   *
   * Keyed by model rather than set once for the provider because thinking is
   * a model capability, not an account one: the same key reaches both a
   * reasoning model and a plain one, and sending a thinking parameter to the
   * plain one is an API error, not a no-op. An absent entry sends nothing,
   * which is what makes an un-dialled model safe by default.
   */
  modelReasoning?: Record<string, AiModelReasoningSetting>;
  /** Capability metadata fetched from models.dev for offline-safe rendering. */
  modelReasoningOptions?: Record<string, AiModelReasoningOption[]>;
}

/**
 * The thinking dial, in the writer's words rather than any one provider's.
 * `"off"` is a request, not an absence: on a reasoning model, asking it not
 * to think and saying nothing at all are different instructions.
 */
export type AiReasoningEffort = "low" | "medium" | "high" | "xhigh" | "max";

export type AiModelReasoningOption =
  | { type: "effort"; values: Array<AiReasoningEffort | null> }
  | { type: "toggle" }
  | { type: "budget_tokens"; min: number; max: number };

export type AiModelReasoningSetting =
  | { type: "effort"; value: AiReasoningEffort }
  | { type: "toggle"; value: boolean }
  | { type: "budget_tokens"; value: number };

export interface AiModelModalities {
  input: string[];
  output: string[];
}

export type AiFeature =
  | "persona-feedback"
  | "persona-reply"
  | "persona-rewrite"
  | "persona-analysis"
  | "room-synthesis"
  | "rubric-judge"
  | "rubric-review"
  | "voice-narration"
  | "voice-transcription"
  | "comment-reply"
  | "citation-format"
  | "source-summarize"
  | "source-detect-missing"
  | "research-web-search"
  | "research-extract"
  | "interview-turn"
  | "dossier-check";

/** Private context the room may use to speak to this writer as a person. */
export interface WriterProfile {
  /** Name the editors should use when addressing the writer. */
  displayName: string;
  /** Personal context that is useful to the room, one fact or detail per line. */
  personalFacts: string;
  /** How much pressure the writer wants in ordinary feedback. */
  feedbackStyle: "direct" | "balanced" | "gentle";
  /** Writer-authored guidance about what feedback should notice or avoid. */
  feedbackNotes: string;
}

export const DEFAULT_WRITER_PROFILE: WriterProfile = {
  displayName: "",
  personalFacts: "",
  feedbackStyle: "balanced",
  feedbackNotes: "",
};

/** Writer-level preferences (identity, feedback, and onboarding). */
export interface WriterSettings {
  /** Form-based AntiTabulaRasa vs the conversational interview. */
  interviewStyle: "form" | "conversational";
  /** Private, account-local context included in editorial-room prompts. */
  profile: WriterProfile;
}

export const DEFAULT_WRITER_SETTINGS: WriterSettings = {
  interviewStyle: "form",
  profile: { ...DEFAULT_WRITER_PROFILE },
};

export type ApparatusCitationStyle = "mla" | "apa" | "chicago";

/**
 * Where claim-checking searches go.
 *
 *  - hosted:           Twyne's own service, using the server's provider key.
 *  - search-api:       a search API called straight from this browser (BYOK),
 *                      configured by `searchBackend`.
 *  - model-web-search: the writer's own model provider, with web search on.
 *  - web-mcp:          tools discovered from the writer's MCP servers.
 */
export type ApparatusResearchProvider =
  | "hosted"
  | "search-api"
  | "model-web-search"
  | "web-mcp";

/**
 * Search APIs Twyne knows how to speak without configuration. "custom" covers
 * anything else that returns JSON: give it a URL and where the results live.
 */
export type SearchBackendId =
  | "tinyfish"
  | "exa"
  | "tavily"
  | "brave"
  | "serper"
  | "custom";

export interface SearchBackendConfig {
  id: SearchBackendId;
  apiKey: string;
  /** Overrides the adapter's built-in endpoint. Required for "custom". */
  baseUrl: string;
  /**
   * "custom" only: dotted path to the results array in the response
   * (e.g. "data.results"). Empty means search the response for the first
   * array of objects that carry a url.
   */
  resultsPath: string;
}

export const DEFAULT_SEARCH_BACKEND: SearchBackendConfig = {
  id: "tinyfish",
  apiKey: "",
  baseUrl: "",
  resultsPath: "",
};

/** Streamable HTTP is the current spec transport; SSE is the deprecated one. */
export type McpTransportKind = "http" | "sse";

/**
 * How to reach the server. Most hosted MCP servers send no CORS headers, so
 * "auto" tries the browser first (token stays on the device) and relays through
 * Convex only once a direct attempt has failed.
 */
export type McpConnectionMode = "auto" | "direct" | "proxy";

export interface McpServerConfig {
  id: string;
  label: string;
  url: string;
  transport: McpTransportKind;
  bearerToken: string;
  enabled: boolean;
  connection: McpConnectionMode;
  /** Tool that answers apparatus claim searches. Empty means auto-detect. */
  searchToolName: string;
  /** Offer this server's tools to the model while drafting. */
  exposeToModel: boolean;
  /** Treat this server's resources as citable knowledge-base material. */
  useResources: boolean;
}

export const DEFAULT_MCP_SERVER: Omit<McpServerConfig, "id"> = {
  label: "",
  url: "",
  transport: "http",
  bearerToken: "",
  enabled: true,
  connection: "auto",
  searchToolName: "",
  exposeToModel: false,
  useResources: true,
};

export interface ApparatusSettings {
  defaultCitationStyle: ApparatusCitationStyle;
  aiEnhanceCitations: boolean;
  flagMissingSources: boolean;
  /** Insert newly researched sources as footnotes at their draft anchors. */
  autoInsertFootnotes: boolean;
  researchProvider: ApparatusResearchProvider;
  searchBackend: SearchBackendConfig;
  /** Sources requested per claim, whichever provider answers. */
  maxResults: number;
  mcpServers: McpServerConfig[];
}

export const DEFAULT_APPARATUS_SETTINGS: ApparatusSettings = {
  defaultCitationStyle: "mla",
  aiEnhanceCitations: true,
  flagMissingSources: false,
  autoInsertFootnotes: false,
  researchProvider: "hosted",
  searchBackend: { ...DEFAULT_SEARCH_BACKEND },
  maxResults: 8,
  mcpServers: [],
};

export interface AiFeatureOverride {
  providerId?: string;
  model?: string;
  temperature?: number;
  maxTokens?: number;
  voice?: string;
  speed?: number;
  responseFormat?: "mp3" | "opus" | "aac" | "flac" | "wav" | "pcm";
  instructions?: string;
}

export interface AiSettings {
  advancedMode: boolean;
  providers: AiProviderConfig[];
  defaultProviderId: string | null;
  perFeature: Partial<Record<AiFeature, AiFeatureOverride>>;
  showProviderTags: boolean;
}

export const DEFAULT_AI_SETTINGS: AiSettings = {
  advancedMode: false,
  providers: [],
  defaultProviderId: null,
  perFeature: {},
  showProviderTags: false,
};

/* ── Provider metadata (labels, defaults) ───────────────────────── */

export interface ProviderMeta {
  type: AiProviderType;
  label: string;
  defaultModels: string[];
  needsBaseUrl: boolean;
  defaultBaseUrl?: string;
  apiKeyOptional?: boolean;
  defaultApiKey?: string;
  /**
   * Speaks and listens but cannot think. A voice-only provider is never
   * offered to the persona, rubric or interview features, and — crucially —
   * having one configured does not make {@link hasConfiguredAiProvider} true,
   * because those features would then take the BYOK path and find no model.
   */
  voiceOnly?: boolean;
}

/** Provider types that do speech but not language. */
export const VOICE_ONLY_PROVIDER_TYPES: ReadonlyArray<AiProviderType> = [
  "fishaudio",
  "supertonic",
];

export const PROVIDER_METAS: ProviderMeta[] = [
  {
    type: "openai",
    label: "OpenAI",
    defaultModels: ["gpt-5.5", "gpt-5.5-mini", "gpt-5.5-nano"],
    needsBaseUrl: false,
  },
  {
    type: "anthropic",
    label: "Anthropic",
    defaultModels: ["claude-sonnet-4-6", "claude-haiku-4-6"],
    needsBaseUrl: false,

