/**
 * Unread counts for the editorial board tabs.
 *
 * The four panels sit mounted-but-hidden, so work that lands in a panel the
 * writer isn't looking at is invisible — the background room can leave five
 * notes in Cast and the writer, staring at Marginalia, never knows. This is
 * the smallest thing that fixes it: a count per tab, cleared when the tab is
 * opened.
 *
 * It listens to events the app already emits rather than asking the panels to
 * report in, so the panels stay unaware of it and no wiring can drift.
 */

export type PanelId =
  | "personas"
  | "rubric"
  | "comments"
  | "citations"
  | "history";

export type ActivityCounts = Record<PanelId, number>;

const EMPTY: ActivityCounts = {
  personas: 0,
  rubric: 0,
  comments: 0,
  citations: 0,
  history: 0,
};

const counts: ActivityCounts = { ...EMPTY };

/** The tab currently on screen. Activity there is seen, not unread. */
let visiblePanel: PanelId | null = null;

function emit(): void {
  if (typeof window === "undefined") return;
  window.dispatchEvent(
    new CustomEvent("twyne:panel-activity", { detail: { ...counts } }),
  );
}

export function panelActivity(): ActivityCounts {
  return { ...counts };
}

export function bump(panel: PanelId, by = 1): void {
  if (panel === visiblePanel) return;
  counts[panel] += by;
  emit();
}

export function clearPanel(panel: PanelId): void {
  if (counts[panel] === 0) return;
  counts[panel] = 0;
  emit();
}

/**
 * Tell the tracker which tab is on screen. Clears that tab's count, because
 * looking at a panel is what "read" means here.
 */
export function setVisiblePanel(panel: PanelId | null): void {
  visiblePanel = panel;
  if (panel) clearPanel(panel);
}

/**
 * Subscribe to the events that constitute activity. Returns a teardown.
 *
===FISH VOICE===

/* ── Public: generate speech client-side (BYOK) ─────────────────── */

export interface VoiceSpeechRequest {
  text: string;
  voice?: string;
  instructions?: string;
  responseFormat?: "mp3" | "opus" | "aac" | "flac" | "wav" | "pcm";
  speed?: number;
  signal?: AbortSignal;
  onAlignment?: (snapshot: SpeechAlignmentSnapshot) => void;
}

export interface VoiceSpeechResult {
  audio?: Blob;
  /** Native provider bytes as they arrive; preferred over waiting for `audio`. */
  audioStream?: ReadableStream<Uint8Array>;
  mimeType: string;
  provider: string;
  model: string;
  voice: string;
  responseFormat: string;
}

export async function runClientVoiceSpeech(
  req: VoiceSpeechRequest,
  settings: AiSettings,
): Promise<VoiceSpeechResult | null> {
  const resolved = resolveFeatureConfig(settings, "voice-narration");
  if (!resolved) return null;
  if (
    !supportsVoiceFeature(
      resolved.provider.type,
      "voice-narration",
      resolved.provider,
    )
  ) {
    reportApplicationDiagnostic(
      "twyne:ai-client:voice-unsupported-provider",
      createAppError("CONFIGURATION_ERROR", { source: "provider" }),
    );
    return null;
  }

  const input = req.text.trim().slice(0, 4096);
  if (!input) return null;
  const generationTraceId = createAiTraceId("voice-narration");
  const folioId = await loadActiveFolioIdFromIdb();
  const usageBase = {
    traceId: generationTraceId,
    attempt: 1,
    source: clientUsageSourceForProvider(resolved.provider),
    feature: "voice-narration" as const,
    provider: resolved.provider.type,
    model: resolved.model,
    folioId: folioId ?? undefined,
    editorialActionId: `${generationTraceId}:action`,
  };

  const override = settings.perFeature["voice-narration"];
  const voice = req.voice ?? override?.voice ?? "alloy";
  const responseFormat =
    req.responseFormat ?? override?.responseFormat ?? "mp3";
  const speed = req.speed ?? override?.speed;
  const instructions = req.instructions ?? override?.instructions;

  if (resolved.provider.type === "fishaudio") {
    try {
      const result = await runFishAudioSpeech({
        provider: resolved.provider,
        model: resolved.model,
        text: input,
        voice,
        responseFormat,
        speed,
        signal: req.signal,
        onAlignment: req.onAlignment,
      });
      await settleClientUsage({
        ...usageBase,
        requestSent: true,
        outcome: "completed",
      });
      return result;
    } catch (error) {
      await settleClientUsage({
        ...usageBase,
        requestSent: true,
        outcome: "failed",
      });
      throw error;
