  } catch (err) {
    await captureAiGeneration({
      feature,
      provider: resolved.provider.type,
      model: resolved.model,
      system,
      prompt,
      latencyMs: performance.now() - start,
      temperature: resolved.temperature,
      maxTokens: resolved.maxTokens,
      spanName,
      traceId: generationTraceId,
      error: err,
      evalSignals,
    });
